//! Everything lying in Pharloom's rooms: mask shards, spool fragments, tools
//! and items on the ground, rosary caches and rocks, shell shard fossils. The
//! save remembers each by its room and its object's name (`persistentBools`,
//! `persistentInts`, `geoRocks`); its place in the room comes from the
//! game's scenes, as a fraction of the room's size (from the left, from the
//! bottom; negative when the scene does not say its size).

use hundo_sdk::{Item, Status};
use serde_json::Value;

#[derive(Clone, Copy, PartialEq)]
pub enum Kind {
    Mask,
    Spool,
    Tool,
    Item,
    Rosary,
    Rock,
    Fossil,
}

pub struct P {
    pub scene: &'static str,
    pub id: &'static str,
    pub kind: Kind,
    /// What picking it up gives: a tool or item of the game, by name.
    pub gives: &'static str,
    /// Its name's key in the game's language sheets.
    pub text: &'static str,
    pub x: f32,
    pub y: f32,
}

