impl Kind {
    pub fn label(self, fr: bool) -> &'static str {
        match (self, fr) {
            (Kind::Mask, true) => "Fragment de masque",
            (Kind::Mask, false) => "Mask shard",
            (Kind::Spool, true) => "Fragment de bobine",
            (Kind::Spool, false) => "Spool fragment",
            (Kind::Tool, true) => "Outil",
            (Kind::Tool, false) => "Tool",
            (Kind::Item, true) => "Objet",
            (Kind::Item, false) => "Item",
            (Kind::Rosary, true) => "Cache de chapelets",
            (Kind::Rosary, false) => "Rosary cache",
            (Kind::Rock, true) => "Rocher de chapelets",
            (Kind::Rock, false) => "Rosary rock",
            (Kind::Fossil, true) => "Fossile d'éclats",
            (Kind::Fossil, false) => "Shell shard fossil",
        }
    }
}

/// The item a pickup stands for, by id.
pub fn item_id(p: &P) -> String {
    format!("pick-{}-{}", p.scene, p.id)
}

/// Whether the save has a room's object taken or broken.
pub fn taken(scenes: Option<&Value>, p: &P) -> bool {
    let list = |key: &str| scenes.and_then(|s| s[key]["serializedList"].as_array()).into_iter().flatten();
    let here = |r: &&Value| r["SceneName"].as_str().is_some_and(|s| s.eq_ignore_ascii_case(p.scene)) && r["ID"] == p.id;
    match p.kind {
        // Hits left: none once broken.
        Kind::Rock => list("geoRocks").filter(here).any(|r| r["Value"].as_i64() == Some(0)),
        Kind::Fossil => list("persistentInts").filter(here).any(|r| r["Value"].as_i64() == Some(0)),
        _ => list("persistentBools").filter(here).any(|r| r["Value"] == true),
    }
}

/// Every pickup of one kind as an item, named after what it gives.
pub fn items(kind: Kind, scenes: Option<&Value>, words: &crate::Words, fr: bool, area_of_scene: &dyn Fn(&str) -> Option<String>) -> Vec<Item> {
    PICKUPS
        .iter()
        .filter(|p| p.kind == kind)
        .map(|p| {
            let area = area_of_scene(p.scene);
            let what = words.get(p.text).unwrap_or_else(|| if p.gives.is_empty() { kind.label(fr).to_string() } else { p.gives.replace('_', " ") });
            let title = match &area {
                Some(a) => format!("{what} · {a}"),
                None => what,
            };
            let mut item = Item::new(item_id(p), title, if taken(scenes, p) { Status::Done } else { Status::Todo });
            // The inventory's own picture of what it gives.
            let picture = match kind {
                Kind::Rosary => Some("I_rosary_icon_clean"),
                Kind::Rock => Some("I_rosary_icon_big_clean"),
                Kind::Fossil => Some("Shell_shard_icon"),
                _ => crate::icons::of(p.gives),
            };
            if let Some(p) = picture {
                item = item.image(format!("game:{p}"));
            }
            if let Some(a) = area {
                item = item.location(a);
            }
            item
        })
        .collect()
}

/// Where a scene's object lies: (scene, fraction from the left, from the bottom).
pub fn spot(scene: &str, id: &str) -> Option<&'static P> {
    PICKUPS.iter().find(|p| p.scene.eq_ignore_ascii_case(scene) && p.id == id)
}

/// Where a tool lies on the ground, by any of its names.
pub fn tool_spot(names: &[String]) -> Option<&'static P> {
    PICKUPS.iter().find(|p| p.kind == Kind::Tool && names.iter().any(|n| n == p.gives))
}
